func validateImportsOrder(s string) ([]string, *string) {
	parts := strings.Split(s, ",")
	allowed := map[string]bool{
		"std": true, "general": true, "company": true, "project": true, "blanked": true, "dotted": true,
	}
	seen := map[string]bool{}
	order := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if !allowed[p] {
			msg := fmt.Sprintf("unknown order group type: %q", p)
			return nil, &msg
		}
		if seen[p] {
			msg := "use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\""
			return nil, &msg
		}
		seen[p] = true
		order = append(order, p)
	}
	for _, req := range []string{"std", "general", "company", "project"} {
		if !seen[req] {
			msg := "use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\""
			return nil, &msg
		}
	}
	return order, nil
}

func parseCSV(s string) []string {
	if s == "" {
		return nil
	}
	items := strings.Split(s, ",")
	out := make([]string, 0, len(items))
	for _, it := range items {
		it = strings.TrimSpace(it)
		if it != "" {
			out = append(out, filepath.ToSlash(it))
		}
	}
	return out
}

func detectProjectName() (string, error) {
	b, err := os.ReadFile("go.mod")
	if err != nil {
		return "", err
	}
	for _, line := range strings.Split(string(b), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(strings.TrimPrefix(line, "module ")), nil
		}
	}
	return "", errors.New("module name not found in go.mod")
}

func processTarget(target string, opts *options, order []string, excludes []string) (result, error) {
	if opts.output != "file" && opts.output != "write" && opts.output != "stdout" {
		return result{}, fmt.Errorf("invalid output %q specified", opts.output)
	}

	root := target
	recursive := opts.recursive
	if target == "./..." {
		root = "."
		recursive = true
	}

	st, err := os.Stat(root)
	if err == nil && st.IsDir() {
		return processDirectory(root, recursive, opts, order, excludes)
	}

	// Nonexistent paths and unusual ./...-like patterns are treated as files.
	return processOneFile(root, true, opts, order)
}

func processDirectory(root string, recursive bool, opts *options, order []string, excludes []string) (result, error) {
	var files []string
	if recursive {
		err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if path == root {
				return nil
			}
			rel, _ := filepath.Rel(root, path)
			rel = filepath.ToSlash(rel)
			if d.IsDir() {
				name := d.Name()
				if name == ".git" || matchesExclude(rel, true, excludes) {
					return filepath.SkipDir
				}
				return nil
			}
			if matchesExclude(rel, false, excludes) {
				return nil
			}
			if strings.HasSuffix(path, ".go") {
				files = append(files, path)
			}
			return nil
		})
		if err != nil {
			return result{}, err
		}
	} else {
		entries, err := os.ReadDir(root)
		if err != nil {
			return result{}, err
		}
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			name := e.Name()
			if !strings.HasSuffix(name, ".go") {
				continue
			}
			if matchesExclude(filepath.ToSlash(name), false, excludes) {
				continue
			}
			files = append(files, filepath.Join(root, name))
		}
	}
	sort.Strings(files)
	changedExit := false
	for _, f := range files {
		res, err := processOneFile(f, false, opts, order)
		if err != nil {
			return result{}, err
		}
		if res.changedForExit {
			changedExit = true
		}
	}
	return result{changedForExit: changedExit}, nil
}

func matchesExclude(rel string, isDir bool, patterns []string) bool {
	rel = filepath.ToSlash(rel)
	for _, pat := range patterns {
		p := filepath.ToSlash(strings.TrimSpace(pat))
		if p == "" {
			continue
		}
		if strings.HasSuffix(p, "/") {
			base := strings.TrimSuffix(p, "/")
			if rel == base || strings.HasPrefix(rel, base+"/") {
				return true
			}
			continue
		}
		if ok, _ := filepath.Match(p, rel); ok {
			return true
		}
		if isDir && (rel == p || strings.HasPrefix(rel, p+"/")) {
			return true
		}
	}
	return false
}

func processOneFile(path string, explicitFile bool, opts *options, order []string) (result, error) {
	abs, _ := filepath.Abs(path)
	src, err := os.ReadFile(abs)
	if err != nil {
		return result{}, err
	}

	formatted, generated, err := transform(abs, src, opts, order)
	if err != nil {
		return result{}, err
	}

	changed := !bytes.Equal(src, formatted)

	if generated && !opts.applyGenerated {
		// Generated files are parsed and can be listed as different, but they are not
		// changed and do not affect -set-exit-status unless explicitly opted in.
		if opts.listDiff {
			if changed {
				fmt.Println(abs)
			}
		} else if opts.output == "stdout" && explicitFile {
			_, _ = os.Stdout.Write(src)
		}
		return result{}, nil
	}

	if opts.listDiff {
		if changed {
			fmt.Println(abs)
			if opts.output == "write" {
				if err := os.WriteFile(abs, formatted, 0644); err != nil {
					return result{}, err
				}
			}
		}
		return result{changedForExit: changed}, nil
	}

	if opts.output == "stdout" && explicitFile {
		_, _ = os.Stdout.Write(formatted)
	} else if opts.output == "file" || opts.output == "write" || !explicitFile {
		if changed {
			if err := os.WriteFile(abs, formatted, 0644); err != nil {
				return result{}, err
			}
		}
	}
	return result{changedForExit: changed}, nil
}

func transform(filename string, src []byte, opts *options, order []string) ([]byte, bool, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
	if err != nil {
		return nil, false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %v", err)
	}
	generated := isGenerated(file)

	decls, specs := extractImports(fset, file, src)
	newSrc := src
	if len(decls) > 0 {
		if opts.setAlias {
			applyAliases(specs)
		}
		if opts.rmUnused {
			specs = filterUnused(file, specs)
		}
		sorted := orderImports(specs, opts, order)
		useSingle := len(sorted) == 1 && len(decls) == 1 && !decls[0].Paren
		importText := renderImports(sorted, useSingle)
		start := decls[0].Start
		end := decls[len(decls)-1].End
		buf := make([]byte, 0, len(src)+len(importText))
		buf = append(buf, src[:start]...)
		buf = append(buf, importText...)
		buf = append(buf, src[end:]...)
		newSrc = buf
	}

	formatted, err := format.Source(newSrc)
	if err != nil {
		return nil, generated, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %v", err)
	}
	if opts.formatExtra {
		formatted = addBlankLinesBetweenFuncs(formatted)
	}
	return formatted, generated, nil
}

func isGenerated(file *ast.File) bool {
	if len(file.Comments) == 0 || len(file.Comments[0].List) == 0 {
		return false
	}
	return strings.HasPrefix(file.Comments[0].List[0].Text, "// Code generated")
}

func extractImports(fset *token.FileSet, file *ast.File, src []byte) ([]importDeclInfo, []importSpec) {
	var decls []importDeclInfo
	var specs []importSpec
	idx := 0
	for _, d := range file.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		start := fset.Position(gd.Pos()).Offset
		end := fset.Position(gd.End()).Offset
		end = lineEnd(src, end)
		decls = append(decls, importDeclInfo{Start: start, End: end, Paren: gd.Lparen.IsValid()})
		for _, sp := range gd.Specs {
			is := sp.(*ast.ImportSpec)
			path, _ := strconv.Unquote(is.Path.Value)
			name := ""
			if is.Name != nil {
				name = is.Name.Name
			}
			comment := ""
			if is.Comment != nil && len(is.Comment.List) > 0 {
				cstart := fset.Position(is.Comment.List[0].Pos()).Offset
				cend := fset.Position(is.Comment.List[len(is.Comment.List)-1].End()).Offset
				if cstart >= 0 && cend >= cstart && cend <= len(src) {
					comment = string(src[cstart:cend])
				}
			}
			specs = append(specs, importSpec{Path: path, Name: name, Comment: comment, Index: idx})
			idx++
		}
	}
	if len(decls) > 1 {
		// Merge declarations by replacing everything between the first and last.
		decls = []importDeclInfo{{Start: decls[0].Start, End: decls[len(decls)-1].End, Paren: true}}
	}
	return decls, specs
}

func lineEnd(src []byte, off int) int {
	if off < 0 {
		return 0
	}
	if off > len(src) {
		return len(src)
	}
	for off < len(src) && src[off] != '\n' && src[off] != '\r' {
		off++
	}
	return off
}

var versionSuffixRE = regexp.MustCompile(`^v[0-9]+$`)

func applyAliases(specs []importSpec) {
	for i := range specs {
		if specs[i].Name != "" {
			continue
		}
		parts := strings.Split(specs[i].Path, "/")
		if len(parts) < 2 {
			continue
		}
		if versionSuffixRE.MatchString(parts[len(parts)-1]) {
			alias := sanitizeIdentifier(parts[len(parts)-2])
			if alias != "" {
				specs[i].Name = alias
			}
		}
	}
}

func sanitizeIdentifier(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	var b strings.Builder
	for i, r := range s {
		ok := r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (i > 0 && r >= '0' && r <= '9')
		if ok {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func filterUnused(file *ast.File, specs []importSpec) []importSpec {
	used := map[string]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.ImportSpec:
			return false
		case *ast.SelectorExpr:
			if id, ok := x.X.(*ast.Ident); ok {
				used[id.Name] = true
			}
		case *ast.Ident:
			// This helps with aliases used in unusual constructs and keeps the
			// heuristic permissive.
			used[x.Name] = true
		}
		return true
	})
	out := make([]importSpec, 0, len(specs))
	for _, sp := range specs {
		if sp.Name == "_" || sp.Name == "." {
			out = append(out, sp)
			continue
		}
		name := sp.Name
		if name == "" {
			name = defaultImportName(sp.Path)
		}
		if used[name] {
			out = append(out, sp)
		}
	}
	return out
}

func defaultImportName(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) == 0 {
		return path
	}
	last := parts[len(parts)-1]
	if versionSuffixRE.MatchString(last) && len(parts) >= 2 {
		last = parts[len(parts)-2]
	}
	// Common import paths can contain dots or dashes even though package names do not.
	last = strings.TrimSuffix(last, ".git")
	last = strings.ReplaceAll(last, "-", "_")
	if idx := strings.LastIndex(last, "."); idx >= 0 && idx+1 < len(last) {
		last = last[:idx]
	}
	return sanitizeIdentifier(last)
}

func orderImports(specs []importSpec, opts *options, order []string) []importSpec {
	companyPrefixes := parseCSV(opts.company)
	orderHas := map[string]bool{}
	for _, g := range order {
		orderHas[g] = true
	}
	groups := map[string][]importSpec{}
	for _, sp := range specs {
		g := classifyImport(sp, opts.projectName, companyPrefixes, orderHas)
		groups[g] = append(groups[g], sp)
	}
	for g := range groups {
		sort.SliceStable(groups[g], func(i, j int) bool {
			if groups[g][i].Path != groups[g][j].Path {
				return groups[g][i].Path < groups[g][j].Path
			}
			if groups[g][i].Name != groups[g][j].Name {
				return groups[g][i].Name < groups[g][j].Name
			}
			return groups[g][i].Index < groups[g][j].Index
		})
	}
	var out []importSpec
	firstGroup := true
	_ = firstGroup
	for _, g := range order {
		items := groups[g]
		if len(items) == 0 {
			continue
		}
		if opts.separateNamed && g != "blanked" && g != "dotted" {
			var unnamed, named []importSpec
			for _, sp := range items {
				if sp.Name == "" {
					unnamed = append(unnamed, sp)
				} else {
					named = append(named, sp)
				}
			}
			if len(unnamed) > 0 {
				out = append(out, unnamed...)
			}
			if len(named) > 0 {
				if len(unnamed) > 0 {
					out = append(out, importSpec{Path: "", Name: "\x00GROUPBREAK"})
				}
				out = append(out, named...)
			}
		} else {
			out = append(out, items...)
		}
		out = append(out, importSpec{Path: "", Name: "\x00GROUPBREAK"})
	}
	if len(out) > 0 && out[len(out)-1].Name == "\x00GROUPBREAK" {
		out = out[:len(out)-1]
	}
	return out
}

func classifyImport(sp importSpec, projectName string, companyPrefixes []string, orderHas map[string]bool) string {
	if sp.Name == "_" && orderHas["blanked"] {
		return "blanked"
	}
	if sp.Name == "." && orderHas["dotted"] {
		return "dotted"
	}
	if projectName != "" && (sp.Path == projectName || strings.HasPrefix(sp.Path, projectName+"/")) {
		return "project"
	}
	for _, p := range companyPrefixes {
		if p != "" && strings.HasPrefix(sp.Path, p) {
			return "company"
		}
	}
	if isStdImport(sp.Path) {
		return "std"
	}
	return "general"
}

func isStdImport(path string) bool {
	if path == "" {
		return false
	}
	first := path
	if i := strings.Index(path, "/"); i >= 0 {
		first = path[:i]
	}
	return !strings.Contains(first, ".")
}

func renderImports(specs []importSpec, single bool) []byte {
	if len(specs) == 0 {
		return nil
	}
	if single {
		sp := specs[0]
		return []byte("import " + renderSpecLine(sp, false, true))
	}
	var b strings.Builder
	b.WriteString("import (\n")
	for _, sp := range specs {
		if sp.Name == "\x00GROUPBREAK" {
			b.WriteByte('\n')
			continue
		}
		b.WriteByte('\t')
		b.WriteString(renderSpecLine(sp, false, false))
		b.WriteByte('\n')
	}
	b.WriteByte(')')
	return []byte(b.String())
}

func renderSpecLine(sp importSpec, _ bool, duplicateComment bool) string {
	var b strings.Builder
	if sp.Name != "" {
		b.WriteString(sp.Name)
		b.WriteByte(' ')
	}
	b.WriteString(strconv.Quote(sp.Path))
	if sp.Comment != "" {
		b.WriteByte(' ')
		if duplicateComment {
			if strings.HasPrefix(sp.Comment, "//") {
				b.WriteString(sp.Comment)
				b.WriteByte('\t')
				b.WriteString(sp.Comment)
			} else {
				b.WriteString(sp.Comment)
				b.WriteByte(' ')
				b.WriteString(sp.Comment)
			}
		} else {
			b.WriteString(sp.Comment)
		}
	}
	return b.String()
}

var adjacentFuncRE = regexp.MustCompile(`(?m)^}\nfunc `)

func addBlankLinesBetweenFuncs(src []byte) []byte {
	return adjacentFuncRE.ReplaceAll(src, []byte("}\n\nfunc "))
}
